export interface DatasetOptions {
  /** Number of cases to generate. */
  size?: number;
  seed: number;
  /** The moment the batch is detected. Failures are placed just before it. */
  detectedAt: Date;
}

export const DEFAULT_DATASET_SIZE = 50;

/**
 * Build the batch.
 *
 * Archetype counts are allocated by largest remainder rather than drawn per
 * case, so the declared mix holds exactly at any size and a run of 50 cases is
 * not quietly a run of 50 coin flips.
 */
export function generateDataset(options: DatasetOptions): SyntheticCase[] {
  const size = options.size ?? DEFAULT_DATASET_SIZE;
  if (!Number.isInteger(size) || size <= 0) {
    throw new RangeError(`Dataset size must be a positive integer, received ${size}`);
  }

  const order = allocate(size);
  return order.map((archetype, index) => buildCase(archetype, index, options));
}

/** Deterministic archetype allocation, interleaved so any prefix is mixed. */
function allocate(size: number): Archetype[] {
  const entries = Object.entries(SPECS) as Array<[Archetype, ArchetypeSpec]>;
  const totalWeight = entries.reduce((sum, [, spec]) => sum + spec.weight, 0);

  const exact = entries.map(([archetype, spec]) => ({
    archetype,
    exact: (spec.weight / totalWeight) * size,
  }));

  const counts = exact.map((e) => ({ archetype: e.archetype, count: Math.floor(e.exact), remainder: e.exact % 1 }));
  let assigned = counts.reduce((sum, c) => sum + c.count, 0);

  // Largest remainder first, ties broken by declaration order — no randomness.
  const byRemainder = [...counts].sort((a, b) => b.remainder - a.remainder);
  let cursor = 0;
  while (assigned < size) {
    byRemainder[cursor % byRemainder.length]!.count += 1;
    assigned += 1;
    cursor += 1;
  }

  // Interleave by repeatedly taking from whichever archetype is furthest
  // behind its target share. A truncated dataset stays representative.
  const remaining = new Map(counts.map((c) => [c.archetype, c.count]));
  const target = new Map(counts.map((c) => [c.archetype, c.count]));
  const out: Archetype[] = [];

  while (out.length < size) {
    let best: Archetype | null = null;
    let bestDeficit = -Infinity;
    for (const [archetype, left] of remaining) {
      if (left <= 0) continue;
      const total = target.get(archetype) ?? 0;
      const placed = total - left;
      // Deficit = how far behind this archetype's ideal position we are.
      const deficit = total === 0 ? -Infinity : (placed + 1) / total;
      if (best === null || deficit < bestDeficit) {
        best = archetype;
        bestDeficit = deficit;
      }
    }
    if (best === null) break;
    out.push(best);
    remaining.set(best, (remaining.get(best) ?? 0) - 1);
  }

  return out;
}

function buildCase(archetype: Archetype, index: number, options: DatasetOptions): SyntheticCase {
  const { seed, detectedAt } = options;
  const spec = SPECS[archetype];
  const key = (part: string): string => `dataset:${index}:${part}`;

  const reason = pick(spec.reasons, seed, key("reason"));
  const [failureReasonRaw, expected] = reason;

  // The detection layer is the authority on what a reason means. Asserting the
  // mapping here stops the dataset from silently drifting away from the
  // archetype it claims to represent if the patterns are ever edited.
  const failureCode = normaliseFailureReason(failureReasonRaw);
  if (failureCode !== expected) {
    throw new Error(
      `Dataset invariant violated: "${failureReasonRaw}" normalises to ${failureCode}, expected ${expected}`,
    );
  }

  const amountPaise = pick(spec.amounts, seed, key("amount"));
  const method = pick(spec.methods, seed, key("method"));

  // Failures are placed in the few hours before detection, so the batch has a
  // realistic spread of "time since failure" rather than one shared timestamp.
  const failedAt = new Date(
    detectedAt.getTime() - drawInt(seed, key("lag"), 5, 240) * MINUTE_MS,
  );

  const [primary, probability, secondary] = spec.history;
  const profile = draw(seed, key("profile")) < probability ? primary : secondary;

  return {
    index,
    archetype,
    paymentId: `pay_sim_${String(index).padStart(4, "0")}`,
    customer: buildCustomer(profile, index, seed, failedAt),
    amountPaise,
    method,
    failureReasonRaw,
    failureCode,
    attemptNumber: drawInt(seed, key("attempt"), 1, 2),
    failedAt,
  };
}

function buildCustomer(
  profile: HistoryProfile,
  index: number,
  seed: number,
  failedAt: Date,
): SyntheticCustomer {
  const key = (part: string): string => `customer:${index}:${part}`;

  const given = pick(GIVEN_NAMES, seed, key("given"));
  const family = pick(FAMILY_NAMES, seed, key("family"));
  const name = `${given} ${family}`;

  const base = {
    id: `cust_sim_${String(index).padStart(4, "0")}`,
    name,
    // .test is a reserved TLD: these addresses cannot resolve to a real inbox.
    email: `${given.toLowerCase()}.${family.toLowerCase()}${index}@example.test`,
  };

  if (profile === "established") {
    const successes = drawInt(seed, key("successes"), 3, 18);
    const averagePaise = pick(PRICES, seed, key("avg"));
    const lastSuccessDays = drawInt(seed, key("recency"), 20, 70);
    return {
      ...base,
      createdAt: new Date(failedAt.getTime() - drawInt(seed, key("tenure"), 200, 900) * DAY_MS),
      lifetimeValuePaise: successes * averagePaise,
      successfulPaymentsCount: successes,
      failedPaymentsCount: drawInt(seed, key("failures"), 0, 2),
      lastSuccessfulPaymentAt: new Date(failedAt.getTime() - lastSuccessDays * DAY_MS),
    };
  }

  if (profile === "shaky") {
    const successes = drawInt(seed, key("successes"), 1, 2);
    const averagePaise = pick(PRICES, seed, key("avg"));
    return {
      ...base,
      createdAt: new Date(failedAt.getTime() - drawInt(seed, key("tenure"), 30, 240) * DAY_MS),
      lifetimeValuePaise: successes * averagePaise,
      successfulPaymentsCount: successes,
      failedPaymentsCount: drawInt(seed, key("failures"), 2, 5),
      lastSuccessfulPaymentAt: new Date(
        failedAt.getTime() - drawInt(seed, key("recency"), 60, 200) * DAY_MS,
      ),
    };
  }

  // New: has never successfully paid. The agent has no history to lean on.
  return {
    ...base,
    createdAt: new Date(failedAt.getTime() - drawInt(seed, key("tenure"), 1, 30) * DAY_MS),
    lifetimeValuePaise: 0,
    successfulPaymentsCount: 0,
    failedPaymentsCount: drawInt(seed, key("failures"), 0, 1),
    lastSuccessfulPaymentAt: null,
  };
}

function pick<T>(values: readonly T[], seed: number, key: string): T {
  if (values.length === 0) throw new RangeError(`Cannot pick from an empty list (${key})`);
  return values[drawInt(seed, key, 0, values.length - 1)]!;
}

/** The declared composition of a batch, for the report header. */
export function describeMix(dataset: readonly SyntheticCase[]): Array<{
  archetype: Archetype;
  cases: number;
  amountPaise: Paise;
}> {
  return (Object.keys(SPECS) as Archetype[])
    .map((archetype) => {
      const rows = dataset.filter((c) => c.archetype === archetype);
      return {
        archetype,
        cases: rows.length,
        amountPaise: rows.reduce((sum, c) => sum + c.amountPaise, 0),
      };
    })
    .filter((row) => row.cases > 0);
}

/** Total amount the batch puts at risk, before any recovery is attempted. */
export function totalAtRiskPaise(dataset: readonly SyntheticCase[]): Paise {
  return dataset.reduce((sum, c) => sum + c.amountPaise, 0);
}

export const DATASET_PROVENANCE =
  "SYNTHETIC — generated deterministically from a seed. No real customer, payment or amount is represented, and outcomes come from a simulated payment provider, not from a live gateway.";

